package net.tapacywka.teyvatcartographia.render;

/**
 * Icons of the active theme: {@code themes/<theme>/icons/<lower-case name>.png}, 64 x 64 px each (the default set
 * is generated by the project's icon script). {@link IconAtlas} stitches them into an 8 x 8 atlas (room for 64); the
 * declaration order is the cell index.
 */
public enum Icon {
    // UI
    PLAYER, CLOSE, PLUS, MINUS, GEAR, COMPASS, TARGET, LOCATE,
    LIST, LAYERS, PENCIL, TRASH, CHECK, EXPORT, IMPORT, SEARCH, EARTH, KEYBOARD, RESET, VIEW, NEW_PIN,
    // Custom pin types (the seven Genshin Impact custom pins)
    DEMON, QUEST, STAR, MEAT, FLOWER, PICKAXE, HOOK,
    // Operator pin types
    PARTY, STRUCTURE, SIGN,
    // Automatic points
    SPAWN, DEATH,
    // The path over deep water (where a crossing begins)
    SEA;

    public static final int COLUMNS = 8, CELL = 64, ATLAS_W = 512, ATLAS_H = 512;

    public float u0() {
        return (ordinal() % COLUMNS) * CELL / (float) ATLAS_W;
    }

    public float v0() {
        return (ordinal() / COLUMNS) * CELL / (float) ATLAS_H;
    }

    public float u1() {
        return u0() + CELL / (float) ATLAS_W;
    }

    public float v1() {
        return v0() + CELL / (float) ATLAS_H;
    }
}
